"use strict";

// RWF-027's canonical B01. The package's whole callable API is chosen AT
// RUNTIME by a class whose `extends` HERITAGE is a resolvable LOCAL CALL
// with TWO endings -- and BOTH of them prevent the class definition from
// completing, for two DIFFERENT reasons:
//
//     function maybe(flag) {
//       if (flag) { throw new Error("boom"); }   // heritage evaluation
//       return 1;                                // is ABRUPT
//     }                                          //   ...or the VALUE is
//     class Mode extends maybe(FLAG) {}          //   not a valid base
//
// This is NEITHER RWF-020's shape NOR RWF-022's:
//
//   * `maybe` does not always throw, so `cannotCompleteNormally` refuses
//     it -- correctly. RWF-020 has nothing to fire on.
//   * `maybe` has no single unconditional return, so
//     `classifyExactCallReturnValue` is "unknown". RWF-022 has nothing to
//     fire on either.
//
// Yet `Mode` is NEVER bound, on either path, and module evaluation on this
// branch ends at the class definition. An analyzer that asks only about ONE
// ending answers "the class is fine" and binds the whole exported value to
// `safeOp` -- a false NOT_AFFECTED for a package that reaches the sink on
// every load taking the early branch.
//
// See fixtures/commonjs-circular-import-multipath-class-heritage-ground-truth/
// for a real node-executed, ASSERTED proof of BOTH endings.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

// The multi-path heritage factory. Not abrupt, not single-return.
function maybe(flag) {
  if (flag) {
    throw new Error("boom");
  }
  return 1;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // Truthy flag: `maybe` throws and the class definition is never entered.
  // Falsy flag: `maybe` returns 1 and ClassDefinitionEvaluation throws
  // `TypeError: Class extends value 1 is not a constructor or null`.
  class Mode extends maybe(process.env.FIXTURE_LIB_FLAG) {}

  void Mode;
}

module.exports = safeOp;
